/// Java `CharacterStatistics.statByName`: whether this is the name of one.
pub fn is_statistic(name: &str) -> bool {
    CHARACTER_STATISTICS.iter().any(|(_, _, n)| *n == name)
}

/// The dungeons among them, in order (Java `DUNGEON_NAMES`).
pub fn dungeon_names() -> impl Iterator<Item = &'static str> {
    CHARACTER_STATISTICS.iter().filter(|(_, s, _)| *s != -1).map(|(_, _, n)| *n)
}
